"use client";

import { AgentPanel } from "@/components/panels/AgentPanel";
import { ComponentTree } from "@/components/panels/ComponentTree";
import { ResultsDock } from "@/components/panels/ResultsDock";
import { ViewPanel } from "@/components/panels/ViewPanel";
import { Viewport } from "@/components/viewer/Viewport";
import { DockResizer } from "@/components/panels/DockResizer";
import { useApp } from "@/lib/store";
import { useEffect } from "react";

/**
 * Three zones. Everything decided before a run — the spec, the agent, the
 * band — on the left, where a chat lives; the device in the centre; how it
 * is drawn and what it is made of on the right, where a tool keeps its
 * inspector. The inspector is for looking, not deciding, so it can be put
 * away and the conversation takes the room.
 *
 * The device is never crowded out — it is the artifact the whole tool exists
 * to change, and the evidence only makes sense against it. The dock under it
 * holds the candidate table, the S11 sweep and the gallery: those need the
 * centre's width, a 300 px rail would turn them into stamps. It appears when
 * there are results and takes no space before then.
 */
export default function Home() {
  const hasResults = useApp((s) => Object.keys(s.results).length > 0);
  const running = useApp((s) => s.running);
  const loadDefaultDevice = useApp((s) => s.loadDefaultDevice);
  const dockTab = useApp((s) => s.dockTab);
  const dockHeight = useApp((s) => s.dockHeight);
  const setDockHeight = useApp((s) => s.setDockHeight);
  const inspectorOpen = useApp((s) => s.inspectorOpen);

  // The device the solver will read, adopted before anything is asked of it.
  useEffect(() => {
    void loadDefaultDevice();
  }, [loadDefaultDevice]);

  return (
    <div className="flex h-screen flex-col overflow-hidden bg-ink-950 text-fg">
      <div className="flex min-h-0 flex-1">
        {/* The conversation: the spec in, the agent's reasoning out. Wider
            when the inspector is away — that is the point of hiding it. */}
        <aside
          className={`shrink-0 border-r border-ink-800 ${inspectorOpen ? "w-[400px]" : "w-[520px]"}`}
        >
          <AgentPanel />
        </aside>

        {/* The device, and the evidence read against it. */}
        <main className="flex min-w-0 flex-1 flex-col">
          <div className="min-h-0 flex-1">
            <Viewport />
          </div>
          {(hasResults || running) && (
            // The gallery earns more room than a table does: these are the
            // pictures the study exists to produce, and a 280 px rail turns
            // them into stamps.
            <div
              // Automatic until the user says otherwise: a gallery wants more
              // room than a table. Once they drag, their number wins and the
              // animation is dropped — a height that eases toward the cursor
              // feels like lag, not polish.
              className={`relative shrink-0 border-t border-ink-800 ${
                dockHeight === null ? "transition-[height] duration-200" : ""
              }`}
              style={{ height: dockHeight ?? (dockTab === "evidence" ? 440 : 280) }}
            >
              <DockResizer
                height={dockHeight ?? (dockTab === "evidence" ? 440 : 280)}
                onResize={setDockHeight}
              />
              <ResultsDock />
            </div>
          )}
        </main>

        {/* The inspector: how the device is drawn, and its parts. */}
        {inspectorOpen && (
          <aside className="flex w-[300px] shrink-0 flex-col overflow-y-auto border-l border-ink-800">
            <ViewPanel />
            <ComponentTree />
          </aside>
        )}
      </div>
    </div>
  );
}
"use client";

import { create } from "zustand";
import { anchors, phoneV1 } from "./device";
import type {
  AgentMessage,
  Anchor,
  Candidate,
  DeviceSpec,
  Job,
  SimResult,
} from "./types";

export type ViewMode = "system" | "focus";
// Single definition: backend.ts owns it because the backend is what accepts
// these values. Two copies had already drifted apart ("replay" existed in one
// and not the other), which the compiler only caught at the call site.
export type { AgentKind } from "./backend";
import type { AgentKind, BuiltinDevice, MediaArtifact } from "./backend";
import { setSceneDevice } from "./geometry";
export type Layer = "showKeepouts" | "showPins" | "showLabels" | "showShaded";

interface AppState {
  // ---- device
  spec: DeviceSpec;
  anchors: Anchor[];
  /** Backend device id after a .blend upload; null = the built-in Handset A. */
  deviceId: string | null;
  uploading: boolean;
  /** URL of a user-supplied .glb; overrides the procedural handset. */
  modelUrl: string | null;
  modelName: string | null;

  // ---- viewer
  enabledBands: string[];
  focusBand: string | null;
  viewMode: ViewMode;
  /** The right rail: how the device is drawn, and its parts. Hidable. */
  inspectorOpen: boolean;
  explode: number;
  hidden: string[];
  selectedComponent: string | null;
  hoveredComponent: string | null;
  showKeepouts: boolean;
  showPins: boolean;
  showLabels: boolean;
  /** Solid shaded surfaces over the x-ray line art. Off by default: the
   *  wireframe is what lets you see the antenna inside the phone. */
  showShaded: boolean;

  // ---- run
  prompt: string;
  /** mock = the backend's offline heuristic agent; devin = the real one. */
  agent: AgentKind;
  runId: string | null;
  running: boolean;
  planning: boolean;
  engine: string | null;
  /** The real agent died and the heuristic finished the run. Never hide this. */
  agentFellBack: boolean;
  tapeOtherDevice: boolean;
  /** Render this run's own maps, x-ray and field clip once it concludes. */
  media: MediaArtifact[];
  /** Backend stage — 'media' means the evidence is still rendering. */
  stage: string;
  /** The devices that ship with the app, and which one is loaded. */
  builtins: BuiltinDevice[];
  builtinId: string | null;
  /** Height the user dragged the results dock to, in px. Null means the
   *  layout picks — a table and a gallery want different room. */
  dockHeight: number | null;
  /** Which dock view is open. Lives here, not in the dock, because the
   *  layout gives the gallery more height than a table needs. */
  dockTab: "results" | "report" | "evidence";
  error: string | null;
  candidates: Candidate[];
  results: Record<string, SimResult>;
  jobs: Job[];
  placements: Record<string, string>;
  selectedCandidate: string | null;
  messages: AgentMessage[];
  /** The agent's report.md, fetched once the run has finished. */
  report: string | null;

  // ---- actions
  setModel: (url: string | null, name: string | null) => void;
  uploadBlend: (blend: File, materials?: File | null) => Promise<void>;
  toggleBand: (id: string) => void;
  setFocusBand: (id: string | null) => void;
  setViewMode: (m: ViewMode) => void;
  toggleInspector: () => void;
  setExplode: (v: number) => void;
  toggleHidden: (name: string) => void;
  isolateComponent: (name: string | null) => void;
  selectComponent: (name: string | null) => void;
  hoverComponent: (name: string | null) => void;
  toggle: (key: Layer) => void;
  selectCandidate: (id: string | null) => void;
  setPrompt: (p: string) => void;
  setAgent: (a: AgentKind) => void;
  setDockTab: (t: "results" | "report" | "evidence") => void;
  setDockHeight: (px: number | null) => void;
  /** Adopt the device the backend will actually solve. Runs once on mount. */
  loadDefaultDevice: (builtinId?: string) => Promise<void>;
  selectBuiltin: (id: string) => Promise<void>;
  startRun: () => Promise<void>;
  /** Mid-run note to the agent. */
  sendNote: (text: string) => Promise<void>;
  poll: () => Promise<void>;
  reset: () => void;
}

// One band by default: the cheapest useful target. Multi-band is a full
// extra solve on every candidate, so it is asked for, never assumed.
const DEFAULT_BANDS = ["wifi24"];

const EMPTY_RUN = {
  runId: null,
  running: false,
  planning: false,
  engine: null,
  agentFellBack: false,
  tapeOtherDevice: false,
  media: [] as MediaArtifact[],
  stage: "ingest",
  error: null,
  candidates: [] as Candidate[],
  results: {} as Record<string, SimResult>,
  jobs: [] as Job[],
  placements: {} as Record<string, string>,
  selectedCandidate: null,
  messages: [] as AgentMessage[],
  report: null,
};

export const useApp = create<AppState>((set, get) => ({
  spec: phoneV1,
  anchors,
  deviceId: null,
  uploading: false,
  modelUrl: null,
  modelName: null,

  enabledBands: DEFAULT_BANDS,
  focusBand: null,
  viewMode: "system",
  inspectorOpen: true,
  explode: 0,
  hidden: [],
  selectedComponent: null,
  hoveredComponent: null,
  showKeepouts: true,
  showPins: true,
  showLabels: true,
  showShaded: false,

  prompt:
    "Where should the antennas be placed in this device? Pick the type, target band and expected performance for each, and respect the keep-out limits.",
  agent: "devin",
  // On by default: the maps and the field clip are the evidence an RF
  // engineer would actually hand to a mechanical one, and they cost a few
  // seconds after the study has already finished and reported.
  dockTab: "results" as const,
  dockHeight: null as number | null,
  builtins: [] as BuiltinDevice[],
  builtinId: null as string | null,
  ...EMPTY_RUN,

  setModel: (url, name) => set({ modelUrl: url, modelName: name }),

  uploadBlend: async (blend, materials) => {
    const form = new FormData();
    form.append("blend", blend, blend.name);
    if (materials) form.append("materials", materials, materials.name);
    set({ uploading: true, error: null });
    try {
      const res = await fetch("/api/device", { method: "POST", body: form });
      const body = await res.json();
      if (!res.ok) throw new Error(body.error ?? `upload failed (${res.status})`);
      const spec: DeviceSpec = body.spec;
      setSceneDevice(spec.board.size_mm);
      set({
        deviceId: body.deviceId,
        spec,
        anchors: body.anchors,
        enabledBands: get().enabledBands.filter((id) =>
          spec.requirements.bands.some((b) => b.id === id),
        ),
        hidden: [],
        selectedComponent: null,
        modelUrl: body.glbUrl,
        modelName: blend.name,
        ...EMPTY_RUN,
      });
    } catch (e) {
      set({ error: e instanceof Error ? e.message : String(e) });
    } finally {
      set({ uploading: false });
    }
  },

  toggleBand: (id) => {
    const next = get().enabledBands.includes(id)
      ? get().enabledBands.filter((b) => b !== id)
      : [...get().enabledBands, id];
    const ordered = get()
      .spec.requirements.bands.map((b) => b.id)
      .filter((b) => next.includes(b));
    const focus = get().focusBand;
    set({
      enabledBands: ordered,
      focusBand: focus && ordered.includes(focus) ? focus : null,
    });
  },

  setFocusBand: (id) => set({ focusBand: id, viewMode: id ? "focus" : "system" }),
  toggleInspector: () => set({ inspectorOpen: !get().inspectorOpen }),
  setViewMode: (m) =>
    set({
      viewMode: m,
      focusBand: m === "focus" ? (get().focusBand ?? get().enabledBands[0] ?? null) : null,
    }),
  setExplode: (v) => set({ explode: v }),
  toggleHidden: (name) =>
    set({
      hidden: get().hidden.includes(name)
        ? get().hidden.filter((n) => n !== name)
        : [...get().hidden, name],
    }),
  isolateComponent: (name) =>
    set({
      hidden: name
        ? get().spec.components.map((c) => c.name).filter((n) => n !== name)
        : [],
      selectedComponent: name,
    }),
  selectComponent: (name) => set({ selectedComponent: name }),
  hoverComponent: (name) => set({ hoveredComponent: name }),
  toggle: (key) => set({ [key]: !get()[key] } as Partial<AppState>),
  selectCandidate: (id) => set({ selectedCandidate: id }),
  setPrompt: (p) => set({ prompt: p }),
  setDockTab: (t) => set({ dockTab: t }),
  setDockHeight: (px) => set({ dockHeight: px }),
  setAgent: (a) => set({ agent: a }),

  selectBuiltin: async (id) => {
    // Switching device throws the current study away on purpose: candidates,
    // anchors and evidence all belong to the object they were computed on, and
    // showing a phone's placements inside a laptop would be worse than showing
    // nothing.
    if (get().running || get().builtinId === id) return;
    set({ ...EMPTY_RUN, report: null });
    await get().loadDefaultDevice(id);
  },

  loadDefaultDevice: async (builtinId) => {
    // Until this lands the panel shows the canned spec, which is a different
    // object from the one the solver reads. Adopt the real one before the first
    // run so nothing on screen describes geometry nobody is solving.
    if (get().deviceId) return;                 // an uploaded device wins
    try {
      // The catalogue is cheap and only fetched once.
      if (!get().builtins.length) {
        const list = await fetch("/api/builtin-devices", { cache: "no-store" })
          .then((r) => (r.ok ? r.json() : []))
          .catch(() => []);
        set({ builtins: list as BuiltinDevice[] });
      }
      const want = builtinId ?? get().builtinId;
      const bands = get().enabledBands.join(",");
      const q = new URLSearchParams({ bands });
      if (want) q.set("builtin", want);
      const res = await fetch(`/api/device?${q}`, { cache: "no-store" });
      if (!res.ok) return;
      const body = await res.json();
      if (body.fallback || !body.spec) return;  // backend down; keep the built-in
      const spec: DeviceSpec = body.spec;
      const entry = body.builtin as BuiltinDevice | null;
      setSceneDevice(spec.board.size_mm);
      set({
        spec,
        anchors: body.anchors ?? get().anchors,
        // The viewer must draw the object the solver just described, so the
        // model travels with the spec rather than being chosen separately.
        modelUrl: null,
        builtinId: entry?.id ?? get().builtinId ?? get().builtins[0]?.id ?? null,
        enabledBands: get().enabledBands.filter((id) =>
          spec.requirements.bands.some((b) => b.id === id),
        ),
      });
    } catch {
      /* offline: the built-in spec stays, and the panel says which it is */
    }
  },

  startRun: async () => {
    const { enabledBands, prompt, agent, deviceId } = get();
    if (!enabledBands.length) {
      set({ error: "Select at least one band before running." });
      return;
    }
    set({
      ...EMPTY_RUN,
      running: true,
      planning: true,
      messages: [{ id: "u0", role: "user", kind: "text", text: prompt, ts: Date.now() }],
    });
    try {
      const res = await fetch("/api/run", {
        method: "POST",
        headers: { "content-type": "application/json" },
        // Evidence is always rendered: it lands after run_finished and never gates the result.
        // `builtin` says which shipped device to solve when none was uploaded.
        body: JSON.stringify({
          prompt, bands: enabledBands, agent, deviceId,
          builtin: get().builtinId, media: true,
        }),
      });
      if (!res.ok) throw new Error((await res.json()).error ?? "run failed");
      const { runId } = await res.json();
      set({ runId });
      await get().poll();
    } catch (e) {
      set({ running: false, planning: false, error: e instanceof Error ? e.message : String(e) });
    }
  },

  sendNote: async (text) => {
    const runId = get().runId;
    if (!runId || !text.trim()) return;
    const res = await fetch("/api/run", {
      method: "PATCH",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ runId, text }),
    });
    if (!res.ok) {
      set({ error: (await res.json()).error ?? "note not delivered" });
      return;
    }
    set({ error: null });
    await get().poll();
  },

  poll: async () => {
    const runId = get().runId;
    if (!runId) return;
    const res = await fetch(`/api/run?runId=${runId}`);
    if (!res.ok) {
      const body = await res.json().catch(() => ({}));
      set({ running: false, error: body.error ?? "run snapshot unavailable" });
      return;
    }
    const snap = await res.json();
    // The user's prompt is local; the backend echoes only mid-run notes.
    const userMsg = get().messages.find((m) => m.id === "u0");
    const placements: Record<string, string> = snap.placements ?? {};
    const done = !!snap.done;
    set({
      jobs: snap.jobs ?? [],
      results: snap.results ?? {},
      placements,
      candidates: snap.candidates ?? [],
      anchors: snap.anchors?.length ? snap.anchors : get().anchors,
      planning: !!snap.planning,
      running: !done,
      engine: snap.engine ?? get().engine,
      agentFellBack: !!snap.agentFellBack,
      tapeOtherDevice: !!snap.tapeOtherDevice,
      media: snap.media ?? [],
      stage: snap.stage ?? "ingest",
      messages: [...(userMsg ? [userMsg] : []), ...(snap.messages ?? [])],
      error: snap.status === "failed" ? "run failed — see the agent feed" : get().error,
      selectedCandidate:
        get().selectedCandidate ?? (Object.values(placements)[0] as string | undefined) ?? null,
    });
    if (done && !get().report && (snap.artifacts ?? []).includes("report.md")) {
      const r = await fetch(`/api/run?runId=${runId}&artifact=report.md`);
      if (r.ok) set({ report: await r.text() });
    }
  },

  reset: () => set({ ...EMPTY_RUN }),
}));

/**
 * Run endpoint — a thin proxy to the backend. The browser never talks to
 * port 8000 directly; `BACKEND_URL` is server-side.
 *
 *   POST  {prompt, bands, agent?, deviceId?, media?}  -> {runId, agent}
 *   GET   ?runId=                             -> RunSnapshot
 *   GET   ?runId=&artifact=report.md          -> the agent's report, as text
 *   PATCH {runId, text}                       -> mid-run note for the agent
 *
 * A backend that is down is reported as such (503) — there is no local
 * stand-in, so nothing on screen can be mistaken for a simulation.
 */
import { NextResponse } from "next/server";

import {
  AGENT,
  type AgentKind,
  BACKEND_URL,
  createBackendRun,
  postBackendMessage,
  readBackendLog,
  readBackendReport,
  readBackendRun,
  toSnapshot,
} from "@/lib/backend";

export const dynamic = "force-dynamic";

function fail(err: unknown) {
  const msg = err instanceof Error ? err.message : String(err);
  // "backend NNN: ..." is the backend refusing (no Devin credentials, unknown
  // device, bad band) — pass it through. Anything else is the backend not
  // answering at all.
  if (/^backend \d{3}/.test(msg)) return NextResponse.json({ error: msg }, { status: 502 });
  return NextResponse.json(
    { error: `backend unreachable at ${BACKEND_URL} — start it with \`cd backend && uv run uvicorn app.main:app --port 8000\`` },
    { status: 503 },
  );
}

export async function POST(req: Request) {
  const body = await req.json().catch(() => ({}));
  const bands: string[] = Array.isArray(body.bands) ? body.bands : [];
  const prompt: string = typeof body.prompt === "string" ? body.prompt : "";
  if (!bands.length) {
    return NextResponse.json({ error: "no bands selected" }, { status: 400 });
  }
  // "replay" used to fall through this ladder to AGENT, so picking the
  // recorded Devin run in the UI silently started the heuristic instead —
  // the one substitution this app must never make quietly.
  const agent: AgentKind =
    body.agent === "devin" || body.agent === "mock" || body.agent === "replay"
      ? body.agent
      : AGENT;
  const deviceId: string | null = typeof body.deviceId === "string" ? body.deviceId : null;
  const media: boolean = body.media === true;
  const builtin: string | null = typeof body.builtin === "string" ? body.builtin : null;

  try {
    const runId = await createBackendRun(prompt, bands, agent, deviceId, media, builtin);
    return NextResponse.json({ runId, agent });
  } catch (err) {
    return fail(err);
  }
}

export async function GET(req: Request) {
  const url = new URL(req.url);
  const runId = url.searchParams.get("runId");
  if (!runId) return NextResponse.json({ error: "runId required" }, { status: 400 });

  try {
    if (url.searchParams.get("artifact") === "report.md") {
      const text = await readBackendReport(runId);
      return new Response(text, {
        headers: { "content-type": "text/markdown; charset=utf-8", "cache-control": "no-store" },
      });
    }
    const [run, events] = await Promise.all([readBackendRun(runId), readBackendLog(runId)]);
    return NextResponse.json(toSnapshot(run, events));
  } catch (err) {
    return fail(err);
  }
}

export async function PATCH(req: Request) {
  const body = await req.json().catch(() => ({}));
  const runId: string = typeof body.runId === "string" ? body.runId : "";
  const text: string = typeof body.text === "string" ? body.text.trim() : "";
  if (!runId || !text) return NextResponse.json({ error: "runId and text required" }, { status: 400 });
  try {
    await postBackendMessage(runId, text);
    return NextResponse.json({ ok: true });
  } catch (err) {
    return fail(err);
  }
}
/**
 * Device endpoint.
 *
 *   GET [?bands=]            -> the default device the backend will solve (spec + anchors)
 *   POST multipart           -> passthrough to backend POST /devices: .blend (+ materials.json)
 *                               in, spec + anchors + artifact list out, plus a same-origin
 *                               URL for device.glb so the viewer can load it without CORS
 *   GET ?id=&artifact=name   -> streams that artifact from the backend
 *
 * Extraction needs the backend's Python 3.11 + bpy interpreter (see
 * backend/README.md); when it has none the backend says so and that error is
 * returned verbatim rather than swapped for a different device.
 */
import { NextResponse } from "next/server";

import { BACKEND_URL, normalizeSpec, uploadBackendDevice } from "@/lib/backend";
import { anchors, phoneV1 } from "@/lib/device";

export const dynamic = "force-dynamic";

export async function GET(req: Request) {
  const url = new URL(req.url);
  const id = url.searchParams.get("id");
  const artifact = url.searchParams.get("artifact");
  if (!id || !artifact) {
    // The default device is whatever the backend will actually solve — the
    // real iPhone manifest when it is present. Returning the built-in slab
    // here made the panel claim the solver read nine parts while it read 176.
    const bands = url.searchParams.get("bands") ?? "wifi24";
    const builtin = url.searchParams.get("builtin");
    const q = new URLSearchParams({ bands });
    if (builtin) q.set("device", builtin);
    const res = await fetch(`${BACKEND_URL}/default-device?${q}`, {
      cache: "no-store",
    }).catch(() => null);
    if (res?.ok) {
      const body = (await res.json()) as {
        spec: unknown; anchors: unknown; builtin?: unknown;
      };
      return NextResponse.json({
        spec: normalizeSpec(body.spec as never),
        anchors: body.anchors,
        builtin: body.builtin ?? null,
      });
    }
    // Backend down: the built-in spec is the honest fallback, and the viewer
    // says which one it is holding.
    return NextResponse.json({ spec: phoneV1, anchors, fallback: true });
  }

  const res = await fetch(`${BACKEND_URL}/devices/${id}/artifacts/${artifact}`, {
    cache: "no-store",
  }).catch((e: unknown) => e);
  if (!(res instanceof Response)) {
    return NextResponse.json({ error: `backend unreachable at ${BACKEND_URL}` }, { status: 503 });
  }
  if (!res.ok) {
    return NextResponse.json({ error: await res.text() }, { status: res.status });
  }
  return new Response(res.body, {
    headers: {
      "content-type": res.headers.get("content-type") ?? "application/octet-stream",
      "cache-control": "no-store",
    },
  });
}

export async function POST(req: Request) {
  const form = await req.formData().catch(() => null);
  const blend = form?.get("blend");
  if (!form || !(blend instanceof File)) {
    return NextResponse.json({ error: "multipart field 'blend' (.blend file) required" }, { status: 400 });
  }
  try {
    const dev = await uploadBackendDevice(form);
    if (dev.status !== "ready" || !dev.spec) {
      return NextResponse.json(
        { error: `extraction ${dev.status}: ${dev.error ?? "no spec"}` },
        { status: 422 },
      );
    }
    return NextResponse.json({
      deviceId: dev.device_id,
      spec: normalizeSpec(dev.spec),
      anchors: dev.anchors,
      ambiguities: dev.ambiguities,
      artifacts: dev.artifacts,
      glbUrl: dev.artifacts.includes("device.glb")
        ? `/api/device?id=${encodeURIComponent(dev.device_id)}&artifact=device.glb`
        : null,
    });
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    return NextResponse.json(
      { error: /^backend \d{3}/.test(msg) ? msg : `backend unreachable at ${BACKEND_URL}` },
      { status: /^backend \d{3}/.test(msg) ? 502 : 503 },
    );
  }
}
/**
 * The devices that ship with the app. A thin proxy, like every backend call
 * here; the client uses it to populate the device picker.
 */
import { NextResponse } from "next/server";

import { BACKEND_URL } from "@/lib/backend";

export const dynamic = "force-dynamic";

export async function GET() {
  try {
    const res = await fetch(`${BACKEND_URL}/builtin-devices`, { cache: "no-store" });
    if (!res.ok) return NextResponse.json([]);
    return NextResponse.json(await res.json());
  } catch {
    // Backend down: no picker, which the panel handles by showing the one
    // device it already has.
    return NextResponse.json([]);
  }
}
/**
 * Proxy to the FastAPI backend — the only source of runs the UI shows.
 *
 * Real Devin (or the backend's offline mock agent), real PyNEC solves, real
 * device geometry. This module translates the backend's shapes onto the
 * `RunSnapshot` the store consumes, so nothing in `components/` knows about
 * the wire format:
 *
 *   POST /runs              {prompt, bands, agent, device_id}  -> {run_id}
 *   GET  /runs/{id}                                            -> status, candidates, results, final, spec
 *   GET  /runs/{id}/log                                        -> the event log (agent commentary lives here)
 *   GET  /runs/{id}/artifacts/report.md                        -> the agent's written report
 *   POST /runs/{id}/messages {text}                            -> mid-run note for the agent
 *   POST /devices            multipart blend (+materials)      -> spec, anchors, device.glb
 *
 * `BACKEND_URL` (server-side env, defaults to http://127.0.0.1:8000) points at
 * it. When the backend is unreachable the route handlers return that as an
 * error; there is deliberately no local stand-in that could be mistaken for
 * a simulation.
 */
import type {
  AgentMessage,
  Anchor,
  BandRequirement,
  Bbox,
  Candidate,
  DeviceComponent,
  DeviceSpec,
  Job,
  SimResult,
  Vec3,
} from "./types";

/** What the store consumes: one run's state, derived from the backend. */
export interface RunSnapshot {
  runId: string;
  done: boolean;
  planning: boolean;
  status: BackendRun["status"];
  engine: string;
  jobs: Job[];
  results: Record<string, SimResult>;
  candidates: Candidate[];
  messages: AgentMessage[];
  /** One winning candidate per band id. */
  placements: Record<string, string>;
  anchors: Anchor[];
  artifacts: string[];
  /** True when the orchestrator finished this run on the heuristic agent
   *  because the real one died. Shown, never hidden. */
  agentFellBack: boolean;
  tapeOtherDevice: boolean;
  media: MediaArtifact[];
  /** Backend pipeline stage: ingest | spec | agent_loop | report | media. */
  stage: string;
}

export const BACKEND_URL =
  process.env.BACKEND_URL ?? process.env.NEXT_PUBLIC_BACKEND_URL ?? "http://127.0.0.1:8000";

/** One rendered artifact: a placement map, an x-ray, an S11 plot, a field clip. */
export interface MediaArtifact {
  name: string;
  kind: "image" | "animation";
  title: string;
  caption: string;
  /** Which antenna this picture is of — a multi-band run is several designs. */
  band_id: string;
  /** Proxied through Next: the browser never reaches the backend directly. */
  url: string;
}

/** A device that ships with the app: what the solver reads and the viewer draws. */
export interface BuiltinDevice {
  id: string;
  name: string;
  short: string;
  model_url: string;
  blurb?: string;
  /** The glTF is Y-up and the manifest was turned to Z-up when it was built,
   *  so the viewer has to turn the model the same way to agree with it. */
  viewer_yup?: boolean;
}

export type AgentKind = "devin" | "replay" | "mock";

/** Which agent drives the loop by default. "devin" needs backend/.env credentials. */
export const AGENT: AgentKind = (process.env.AGENT as AgentKind) ?? "mock";

const TIMEOUT_MS = 8000;

// ---------------------------------------------------------------- wire shapes

/** GET /runs/{id}. Candidates/results are keyed by candidate_id. */
export type BackendRun = {
  run_id: string;
  device_id: string | null;
  status: "running" | "finished" | "failed";
  stage: string;
  iteration: number;
  truncated: boolean;
  spec_source: string;
  ambiguities: unknown[];
  artifacts: string[];
  /** Rendered evidence, appended as each render lands after the run ends. */
  media?: (Partial<MediaArtifact> & { name: string; kind: "image" | "animation"; title: string; caption: string })[];
  media_requested?: boolean;
  n_events: number;
  spec: BackendSpec;
  anchors: Anchor[];
  candidates: Record<string, BackendCandidate>;
  results: Record<string, BackendResult>;
  final: BackendFinal | null;
};

/** The backend's DeviceSpec: same as ours minus the viewer-only hints. */
export type BackendSpec = Omit<DeviceSpec, "components"> & {
  components: (Omit<DeviceComponent, "color"> & {
    color?: string;
    role?: string;
    em_source?: string;
  })[];
  geometry_path?: string | null;
};

type BackendCandidate = Omit<Candidate, "keepout_mm"> & {
  params?: Record<string, number>;
};

type BackendResult = SimResult & {
  impedance_ohm?: [number, number];
  // Stamped by the orchestrator after scoring, not by the solver: the solve
  // measures electricals and has no opinion on the keep-out.
  clearance_mm?: number | null;
  meets_clearance?: boolean | null;
};

type BackendFinal = {
  ranking: string[];
  rationale: string;
  truncated: boolean;
  best: BackendResult | null;
  best_candidate: BackendCandidate | null;
  iterations: number;
  total_sims: number;
  spec_source: string;
  agent_report?: Record<string, unknown> | null;
};

export type BackendEvent = {
  run_id: string;
  seq: number;
  ts: number;
  stage: string;
  type:
    | "stage_started"
    | "stage_progress"
    | "agent_message"
    | "candidates_proposed"
    | "sim_started"
    | "sim_result"
    | "iteration_scored"
    | "decision"
    | "artifact"
    | "run_finished"
    | "error";
  payload: Record<string, unknown>;
};

/** POST /devices. */
export type BackendDevice = {
  device_id: string;
  status: "extracting" | "ready" | "failed";
  error?: string | null;
  spec: BackendSpec | null;
  anchors: Anchor[];
  ambiguities: unknown[];
  size_mm: Vec3 | null;
  artifacts: string[];
};

// ---------------------------------------------------------------- transport

async function call<T>(path: string, init?: RequestInit): Promise<T> {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), TIMEOUT_MS);
  try {
    const res = await fetch(`${BACKEND_URL}${path}`, {
      ...init,
      signal: ctrl.signal,
      headers: { "content-type": "application/json", ...(init?.headers ?? {}) },
      cache: "no-store",
    });
    if (!res.ok) {
      throw new Error(`backend ${res.status}: ${(await res.text()).slice(0, 200)}`);
    }
    return (await res.json()) as T;
  } finally {
    clearTimeout(timer);
  }
}

export async function createBackendRun(
  prompt: string,
  bands: string[],
  agent: AgentKind = AGENT,
  deviceId: string | null = null,
  media = false,
  builtin: string | null = null,
): Promise<string> {
  const body = JSON.stringify({
    prompt, bands, agent, device_id: deviceId, media, builtin,
  });
  const out = await call<{ run_id: string }>("/runs", { method: "POST", body });
  return out.run_id;
}

export async function readBackendRun(runId: string): Promise<BackendRun> {
  return call<BackendRun>(`/runs/${runId}`);
}

export async function readBackendLog(runId: string, since = 0): Promise<BackendEvent[]> {
  const out = await call<{ events: BackendEvent[] }>(`/runs/${runId}/log?since=${since}`);
  return out.events;
}

/** The agent's written report, once the run has finished. */
export async function readBackendReport(runId: string): Promise<string> {
  const res = await fetch(`${BACKEND_URL}/runs/${runId}/artifacts/report.md`, { cache: "no-store" });
  if (!res.ok) throw new Error(`backend ${res.status}: ${(await res.text()).slice(0, 200)}`);
  return res.text();
}

export async function postBackendMessage(runId: string, text: string): Promise<void> {
  await call<unknown>(`/runs/${runId}/messages`, {
    method: "POST",
    body: JSON.stringify({ text }),
  });
}

/**
 * Upload a .blend (+ optional materials.json) and wait for extraction. The
 * multipart body is passed through untouched; the backend needs a Python 3.11
 * + bpy interpreter for this (see backend/README.md), and says so in its
 * error when it has none.
 */
export async function uploadBackendDevice(form: FormData): Promise<BackendDevice> {
  // Extraction is a Blender run: far longer than the 8 s call() budget.
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), 10 * 60 * 1000);
  try {
    const res = await fetch(`${BACKEND_URL}/devices`, {
      method: "POST",
      body: form,
      signal: ctrl.signal,
      cache: "no-store",
    });
    if (!res.ok) {
      throw new Error(`backend ${res.status}: ${(await res.text()).slice(0, 300)}`);
    }
    return (await res.json()) as BackendDevice;
  } finally {
    clearTimeout(timer);
  }
}

// ---------------------------------------------------------------- mapping

/** Viewer-only hints the backend does not carry: a colour per EM class. */
const EM_COLOR: Record<string, string> = {
  pec: "#d9a441",
  lossy_metal: "#3f4a63",
  dielectric: "#1f6f4a",
  air: "#1e293b",
};

/** Backend spec -> the spec the viewer draws (adds the display hints). */
export function normalizeSpec(spec: BackendSpec): DeviceSpec {
  return {
    ...spec,
    components: spec.components.map((c) => ({
      ...c,
      color: c.color ?? EM_COLOR[c.em] ?? "#475569",
      opacity: c.em === "dielectric" ? 0.35 : undefined,
      metalness: c.em === "pec" ? 0.85 : c.em === "lossy_metal" ? 0.5 : 0.1,
      roughness: c.em === "pec" ? 0.3 : 0.6,
      shape: "box",
      explode: [0, 0, 0],
    })),
  };
}

function keepoutFor(band: BandRequirement, p: Vec3, size: Vec3): Bbox {
  const [W, H, T] = size;
  const r = band.clearance_mm;
  const rz = Math.min(r, T / 2 + 1.5);
  const cl = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));
  return [
    [cl(p[0] - r, 0, W), cl(p[1] - r, 0, H), cl(p[2] - rz, -1, T)],
    [cl(p[0] + r, 0, W), cl(p[1] + r, 0, H), cl(p[2] + rz, 0, T + 1)],
  ];
}

function fmt(v: number, d = 1) {
  return Number.isFinite(v) ? v.toFixed(d) : "n/a";
}

/**
 * Event log -> the agent feed. Devin's own words (`agent_message`) are what
 * the panel is for; the rest is the orchestrator narrating the loop so a
 * minutes-long real run never looks stuck.
 */
function messagesFrom(
  events: BackendEvent[],
  candidates: Record<string, BackendCandidate>,
  bands: Record<string, BandRequirement>,
): AgentMessage[] {
  const out: AgentMessage[] = [];
  const push = (ev: BackendEvent, role: AgentMessage["role"], kind: AgentMessage["kind"], text: string) =>
    out.push({ id: `e${ev.seq}`, role, kind, text, ts: Math.round(ev.ts * 1000) });
  const bandName = (id: unknown) => (typeof id === "string" && bands[id]?.name) || String(id ?? "");

  for (const ev of events) {
    const p = ev.payload;
    switch (ev.type) {
      case "stage_started": {
        const s = String(p.stage ?? ev.stage);
        if (s === "extract") push(ev, "agent", "step", "Reading the build file (agent-side extraction).");
        else if (s === "agent_loop") push(ev, "agent", "step", "Design loop started: propose, simulate, score, refine.");
        else if (s === "report") push(ev, "agent", "step", "Writing the report.");
        break;
      }
      case "agent_message":
        push(ev, p.role === "user" ? "user" : "agent", "text", String(p.text ?? ""));
        break;
      case "candidates_proposed": {
        const cands = (p.candidates as BackendCandidate[] | undefined) ?? [];
        const sweep = p.sweep as { param?: string; candidate_id?: string } | undefined;
        const by = new Map<string, number>();
        for (const c of cands) by.set(c.band_id, (by.get(c.band_id) ?? 0) + 1);
        const where = [...by].map(([b, n]) => `${n} for ${bandName(b)}`).join(", ");
        push(
          ev,
          "agent",
          "step",
          sweep?.param
            ? `Iteration ${p.iteration}: sweeping ${sweep.param} on ${sweep.candidate_id} (${cands.length} variants).`
            : `Iteration ${p.iteration}: proposed ${cands.length} candidates (${where}).`,
        );
        break;
      }
      case "sim_result": {
        const r = p as unknown as BackendResult;
        const c = candidates[r.candidate_id];
        if (r.status === "failed") {
          push(ev, "agent", "result", `${r.candidate_id}: solve failed. ${r.notes ?? ""}`);
          break;
        }
        push(
          ev,
          "agent",
          "result",
          `${r.candidate_id}${c ? ` (${c.antenna_type}, ${bandName(c.band_id)})` : ""}: ` +
            `S11 ${fmt(r.s11_min_db)} dB at ${fmt(r.resonant_ghz, 3)} GHz, BW ${fmt(r.bandwidth_mhz, 0)} MHz, ` +
            `eff ${fmt(r.efficiency * 100, 0)}%, VSWR ${fmt(r.vswr, 2)} -> ${r.meets_requirements ? "PASS" : "FAIL"}.` +
            (r.notes ? ` ${r.notes}` : ""),
        );
        break;
      }
      case "iteration_scored": {
        const notes = (p.notes as string[] | undefined) ?? [];
        push(
          ev,
          "agent",
          "step",
          `Iteration ${p.iteration} scored: trend ${String(p.trend)}` +
            (p.best_so_far ? `, best so far ${String(p.best_so_far)}` : "") +
            (notes.length ? `. ${notes.join(" ")}` : "."),
        );
        break;
      }
      case "decision":
        push(ev, "agent", "text", `${String(p.decision ?? "decision")}: ${String(p.rationale ?? p.agent_summary ?? "")}`);
        break;
      case "run_finished": {
        if (p.status === "failed") {
          push(ev, "agent", "text", `Run failed: ${String(p.error ?? "unknown error")}`);
          break;
        }
        const best = p.best_candidate as BackendCandidate | null | undefined;
        const r = p.best as BackendResult | null | undefined;
        push(
          ev,
          "agent",
          "text",
          best && r
            ? `Recommendation: ${best.antenna_type} at ${best.position_mm.map((v) => v.toFixed(1)).join(", ")} mm ` +
              `for ${bandName(best.band_id)}, length ${best.length_mm} mm — S11 ${fmt(r.s11_min_db)} dB, ` +
              `efficiency ${fmt(r.efficiency * 100, 0)}%${verdictPhrase(r)}. ` +
              `${String(p.rationale ?? "")}${p.truncated ? " (budget exhausted)" : ""}`

Exit code 1
              `${String(p.rationale ?? "")}${p.truncated ? " (budget exhausted)" : ""}`
            : `Run finished without a simulated design. ${String(p.rationale ?? "")}`,
        );
        break;
      }
      case "artifact":
        if (p.name === "report.md") push(ev, "agent", "step", "Report ready (report.md, run.json, S11 CSVs).");
        break;
      case "error":
        push(ev, "agent", "text", `Error: ${String(p.error ?? "")}`);
        break;
      default:
        break;
    }
  }
  return out;
}

/** Composite ranking used to highlight the best result per band while the loop runs. */
function rank(r: SimResult) {
  return (
    (r.meets_requirements ? 1 : 0) * 2 +
    Math.min(-r.s11_min_db / 20, 1) +
    r.efficiency +
    Math.min(r.bandwidth_mhz / 600, 1) * 0.5
  );
}

/**
 * Backend run + event log -> the snapshot the store consumes.
 *
 * The backend has no per-candidate queue beyond `sim_started`: a candidate
 * exists once proposed and gains a result once solved. Placement (one winner
 * per band) follows the agent's own ranking once it has concluded, and the
 * best complete result so far while it is still running.
 */
/**
 * What the design actually satisfies, said precisely.
 *
 * `meets_requirements` is the solver's flag and it covers S11 and efficiency
 * only — the solve has no opinion on the keep-out, which is geometry. Reading
 * it as "all requirements met" produced a report that claimed every
 * requirement passed while the run itself said "not all margins positive",
 * because the radiator sat 12.6 mm from a steel speaker under a 14 mm
 * keep-out. The orchestrator now stamps the geometric verdict onto each
 * result; this states both.
 */
function verdictPhrase(r: BackendResult): string {
  if (!r.meets_requirements) return ", best effort — electrical spec not met";
  if (r.meets_clearance === false) {
    const gap = r.clearance_mm;
    return `, electrical spec met but ${gap != null ? `${gap} mm ` : ""}clear of the nearest conductor, inside the keep-out`;
  }
  return ", every requirement met";
}

export function toSnapshot(run: BackendRun, events: BackendEvent[]): RunSnapshot {
  const size = run.spec.board.size_mm;
  const bands: Record<string, BandRequirement> = {};
  for (const b of run.spec.requirements.bands) bands[b.id] = b;

  const started = new Set<string>();
  for (const ev of events)
    if (ev.type === "sim_started") started.add(String(ev.payload.candidate_id));

  const candidates: Candidate[] = Object.values(run.candidates).map((c) => {
    const band = bands[c.band_id];
    return {
      ...c,
      keepout_mm: band
        ? keepoutFor(band, c.position_mm, size)
        : [c.position_mm, c.position_mm],
    };
  });

  const results: Record<string, SimResult> = run.results;

  const jobs: Job[] = candidates.map((c) => {
    const r = results[c.candidate_id];
    return {
      job_id: `${run.run_id}__${c.candidate_id}`,
      candidate_id: c.candidate_id,
      band_id: c.band_id,
      status: r ? r.status : started.has(c.candidate_id) ? "running" : "queued",
    };
  });

  const placements: Record<string, string> = {};
  const ranking = run.final?.ranking ?? [];
  for (const bandId of Object.keys(bands)) {
    const fromAgent = ranking.find((cid) => run.candidates[cid]?.band_id === bandId);
    if (fromAgent && results[fromAgent]?.status === "complete") {
      placements[bandId] = fromAgent;
      continue;
    }
    const best = candidates
      .filter((c) => c.band_id === bandId && results[c.candidate_id]?.status === "complete")
      .sort((a, b) => rank(results[b.candidate_id]) - rank(results[a.candidate_id]))[0];
    if (best) placements[bandId] = best.candidate_id;
  }

  return {
    runId: run.run_id,
    done: run.status !== "running",
    planning: run.status === "running" && candidates.length === 0,
    status: run.status,
    stage: run.stage,
    engine: "PyNEC",
    // The orchestrator restarts a dead agent channel on the built-in heuristic
    // so a demo always ends with a result, and marks the run
    // `<source>+mock-fallback`. That is a reasonable default and a terrible
    // thing to hide: a run finished by the heuristic must never be presented
    // as Devin's work. Surface it and let the UI say so.
    agentFellBack: run.spec_source.includes("mock-fallback"),
    // A replayed transcript reasons about the device it was recorded on. The
    // solves below are live against the device actually loaded, but the words
    // are the recording's — say which phone they were about.
    tapeOtherDevice: run.spec_source.includes("tape-other-device"),
    // The backend hands back its own paths; rewrite them onto the Next proxy
    // so the browser can actually load them.
    media: (run.media ?? []).map((m) => ({
      ...m,
      band_id: m.band_id ?? "",
      url: `/api/media/${encodeURIComponent(run.run_id)}/${encodeURIComponent(m.name)}`,
    })),
    jobs,
    results,
    candidates,
    messages: messagesFrom(events, run.candidates, bands),
    placements,
    anchors: run.anchors,
    artifacts: run.artifacts,
  };
}
